    ///Whether this node is a cyclic reference (`Cycle`).
    pub fn is_cycle(&self) -> bool {
        matches!(
            self,
            ParseTree::Direct(Direct::Cycle { .. })
                | ParseTree::MutualC(MutualC::Cycle { .. })
                | ParseTree::MutualB(MutualB::Cycle { .. })
                | ParseTree::ChainC(ChainC::Cycle { .. })
                | ParseTree::ChainA(ChainA::Cycle { .. })
                | ParseTree::ChainB(ChainB::Cycle { .. })
                | ParseTree::SharedA(SharedA::Cycle { .. })
                | ParseTree::SharedB(SharedB::Cycle { .. })
                | ParseTree::TwoExitsC(TwoExitsC::Cycle { .. })
                | ParseTree::TwoExitsB(TwoExitsB::Cycle { .. })
                | ParseTree::TwoRoutesC(TwoRoutesC::Cycle { .. })
                | ParseTree::TwoRoutesA(TwoRoutesA::Cycle { .. })
                | ParseTree::TwoRoutesB(TwoRoutesB::Cycle { .. })
                | ParseTree::Nullable(Nullable::Cycle { .. })
                | ParseTree::SiblingC(SiblingC::Cycle { .. })
                | ParseTree::ParentD(ParentD::Cycle { .. })
                | ParseTree::OverlapC(OverlapC::Cycle { .. })
                | ParseTree::OverlapB(OverlapB::Cycle { .. })
                | ParseTree::IntermediateY(IntermediateY::Cycle { .. })
                | ParseTree::Optional(Optional::Cycle { .. })
                | ParseTree::Grouped(Grouped::Cycle { .. })
                | ParseTree::Plus0(Plus0::Cycle { .. })
                | ParseTree::Plus1(Plus1::Cycle { .. })
                | ParseTree::Opt1(Opt1::Cycle { .. })
                | ParseTree::Group0(Group0::Cycle { .. })
        )
    }
    ///The target of a `Cycle` node as a `ParseTree`, or `None` for any other node.
    ///The target is not among `children()`.
    pub fn cycle_target(&self) -> Option<Self> {
        match self {
            ParseTree::Direct(Direct::Cycle { target }) => Some(ParseTree::Direct(target.get())),
            ParseTree::MutualC(MutualC::Cycle { target }) => Some(ParseTree::MutualC(target.get())),
            ParseTree::MutualB(MutualB::Cycle { target }) => Some(ParseTree::MutualB(target.get())),
            ParseTree::ChainC(ChainC::Cycle { target }) => Some(ParseTree::ChainC(target.get())),
            ParseTree::ChainA(ChainA::Cycle { target }) => Some(ParseTree::ChainA(target.get())),
            ParseTree::ChainB(ChainB::Cycle { target }) => Some(ParseTree::ChainB(target.get())),
            ParseTree::SharedA(SharedA::Cycle { target }) => Some(ParseTree::SharedA(target.get())),
            ParseTree::SharedB(SharedB::Cycle { target }) => Some(ParseTree::SharedB(target.get())),
            ParseTree::TwoExitsC(TwoExitsC::Cycle { target }) => {
                Some(ParseTree::TwoExitsC(target.get()))
            }
            ParseTree::TwoExitsB(TwoExitsB::Cycle { target }) => {
                Some(ParseTree::TwoExitsB(target.get()))
            }
            ParseTree::TwoRoutesC(TwoRoutesC::Cycle { target }) => {
                Some(ParseTree::TwoRoutesC(target.get()))
            }
            ParseTree::TwoRoutesA(TwoRoutesA::Cycle { target }) => {
                Some(ParseTree::TwoRoutesA(target.get()))
            }
            ParseTree::TwoRoutesB(TwoRoutesB::Cycle { target }) => {
                Some(ParseTree::TwoRoutesB(target.get()))
            }
            ParseTree::Nullable(Nullable::Cycle { target }) => {
                Some(ParseTree::Nullable(target.get()))
            }
            ParseTree::SiblingC(SiblingC::Cycle { target }) => {
                Some(ParseTree::SiblingC(target.get()))
            }
            ParseTree::ParentD(ParentD::Cycle { target }) => Some(ParseTree::ParentD(target.get())),
            ParseTree::OverlapC(OverlapC::Cycle { target }) => {
                Some(ParseTree::OverlapC(target.get()))
            }
            ParseTree::OverlapB(OverlapB::Cycle { target }) => {
                Some(ParseTree::OverlapB(target.get()))
            }
            ParseTree::IntermediateY(IntermediateY::Cycle { target }) => {
                Some(ParseTree::IntermediateY(target.get()))
            }
            ParseTree::Optional(Optional::Cycle { target }) => {
                Some(ParseTree::Optional(target.get()))
            }
            ParseTree::Grouped(Grouped::Cycle { target }) => Some(ParseTree::Grouped(target.get())),
            ParseTree::Plus0(Plus0::Cycle { target }) => Some(ParseTree::Plus0(target.get())),
            ParseTree::Plus1(Plus1::Cycle { target }) => Some(ParseTree::Plus1(target.get())),
            ParseTree::Opt1(Opt1::Cycle { target }) => Some(ParseTree::Opt1(target.get())),
            ParseTree::Group0(Group0::Cycle { target }) => Some(ParseTree::Group0(target.get())),
            _ => None,
        }
    }
