impl<'a> ListNode<'a> for Plus0<'a> {
    fn iter(&'a self) -> IntoIter<ParseTree<'a>> {
        let mut items = vec![];
        let mut current = self;
        loop {
            match current {
                Plus0::Alt0 {
                    empty_es_0: rest,
                    empty_e_1: item,
                    ..
                } => {
                    items.push(item.as_parse_tree());
                    current = rest;
                }
                Plus0::Alt1 { empty_e: item, .. } => {
                    items.push(item.as_parse_tree());
                    break;
                }
                Plus0::Amb(_) => {
                    items.push(ParseTree::Plus0(current));
                    break;
                }
                Plus0::Cycle { .. } => {
                    items.push(ParseTree::Plus0(current));
                    break;
                }
            }
        }
        items.reverse();
        items.into_iter()
    }
}
impl<'a> ListNode<'a> for Plus1<'a> {
    fn iter(&'a self) -> IntoIter<ParseTree<'a>> {
        let mut items = vec![];
        let mut current = self;
        loop {
            match current {
                Plus1::Alt0 {
                    empty_es_0: rest,
                    empty_f: sep,
                    empty_e_2: item,
                    ..
                } => {
                    items.push(item.as_parse_tree());
                    items.push(sep.as_parse_tree());
                    current = rest;
                }
                Plus1::Alt1 { empty_e: item, .. } => {
                    items.push(item.as_parse_tree());
                    break;
                }
                Plus1::Amb(_) => {
                    items.push(ParseTree::Plus1(current));
                    break;
                }
                Plus1::Cycle { .. } => {
                    items.push(ParseTree::Plus1(current));
                    break;
                }
            }
        }
        items.reverse();
        items.into_iter()
    }
}
impl<'a> ListNode<'a> for Star0<'a> {
    fn iter(&'a self) -> IntoIter<ParseTree<'a>> {
        match self {
            Star0::Alt0 { opt_0, .. } => match opt_0 {
                Opt0::Alt0 {
                    empty_es: opt_0, ..
                } => opt_0.iter(),
                Opt0::Alt1 { .. } => vec![].into_iter(),
                Opt0::Amb(_) => vec![ParseTree::Opt0(opt_0)].into_iter(),
            },
            Star0::Amb(_) => vec![ParseTree::Star0(self)].into_iter(),
        }
    }
}
